    std::uint64_t aWandererE = 0U; std::uint64_t aWandererF = 0U; std::uint64_t aWandererG = 0U; std::uint64_t aWandererH = 0U;
    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    aIngress = 0x82613785757C9D34ULL;
    aCarry = 0xB6CD676BC263D28EULL;
    aWandererA = 0x982A5A549B39063DULL;
    aWandererB = 0xBBB5938966C79995ULL;
    aWandererC = 0xEA986665FF5A8CAFULL;
    aWandererD = 0xC92EDC059B0D2476ULL;
    aWandererE = 0xDE5729E4D4F535A8ULL;
    aWandererF = 0x8975AC2FE81C2B9AULL;
    aWandererG = 0xDF71169E109F941AULL;
    aWandererH = 0xD2E6B3BE11EB7CCCULL;
    aWandererI = 0xFA7A519A12A23BE8ULL;
    aWandererJ = 0xC1CEFCA17923CCF0ULL;
    aWandererK = 0xA1E0B85ED1E13C10ULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    TwistExpander_Ankaa_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Ankaa_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Ankaa_Arx::TWIST_C(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollB;

